H.background();
const T = Math.max(50, P.T);
const Ea = Math.max(1, P.Ea);
const kT = 8.314e-3 * T;
const v = H.plot2d({ xMin: 0, xMax: 25, yMin: 0, yMax: 0.5 });
v.grid(); v.axes();
function f(E) {
  if (E < 0) return 0;
  return (2 / Math.sqrt(Math.PI)) * Math.pow(kT, -1.5) * Math.sqrt(E) * Math.exp(-E / kT);
}
v.fn(E => f(E), { color: H.colors.accent, width: 3 });
for (let E = Ea; E <= 25; E += 0.4) {
  const yv = f(E);
  if (yv > 0.001) v.line(E, 0, E, yv, { color: H.colors.warn, width: 1 });
}
v.line(Ea, 0, Ea, 0.5, { color: H.colors.violet, width: 2, dash: [5, 5] });
v.text("Ea", Ea + 0.3, 0.46, { color: H.colors.violet, size: 13 });
const frac = Math.exp(-Ea / kT);
const Emol = 12.5 + 11 * Math.sin(t * 1.1);
const reacts = Emol > Ea;
v.dot(Math.max(0.2, Emol), f(Math.max(0.2, Emol)) + 0.02, { r: 7, fill: reacts ? H.colors.good : H.colors.sub });
